#include "gateway_config_page.h"

const char GATEWAY_LOGIN_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
"<title>Đăng nhập Gateway</title><style>:root{font-family:'Segoe UI',system-ui,sans-serif;color:#eef2ff;background:#08111f}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 20% 10%,#12315c,transparent 38%),#08111f}.card{width:min(410px,calc(100% - 28px));padding:30px;border:1px solid #29415f;border-radius:20px;background:#101d30;box-shadow:0 24px 70px #0008}.tag{color:#38bdf8;font-weight:800;font-size:12px;letter-spacing:.12em}h1{margin:10px 0 8px;font-size:28px}.muted{color:#a6b5c9;font-size:14px;line-height:1.5}.field{display:grid;gap:7px;margin-top:16px}label{font-size:13px;font-weight:700}input{width:100%;min-height:48px;border:1px solid #38506d;border-radius:10px;background:#091527;color:#fff;padding:0 13px;font:inherit}input:focus-visible,button:focus-visible{outline:3px solid #38bdf8;outline-offset:2px}button{width:100%;min-height:49px;margin-top:20px;border:0;border-radius:10px;background:#0284c7;color:white;font:800 14px inherit;cursor:pointer}</style></head>"
"<body><main class='card'><div class='tag'>AUBOT GATEWAY</div><h1>Đăng nhập cấu hình</h1><p class='muted'>Quản lý WiFi, Ethernet và máy chủ MQTT của Gateway.</p><form method='post' action='/dang-nhap'><div class='field'><label for='username'>Tên đăng nhập</label><input id='username' name='username' value='admin' autocomplete='username'></div><div class='field'><label for='password'>Mật khẩu</label><input id='password' name='password' type='password' autocomplete='current-password' autofocus></div><button>Đăng nhập</button></form></main></body></html>";

const char GATEWAY_CONFIG_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Cấu hình Gateway</title><style>"
":root{--bg:#08111f;--card:#111e31;--line:#30445f;--text:#f1f5f9;--muted:#a6b5c9;--blue:#0ea5e9;--green:#22c55e;font-family:'Segoe UI',system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 90% -10%,#173a69,transparent 35%),var(--bg);color:var(--text)}button,input,select{font:inherit}:focus-visible{outline:3px solid #38bdf8;outline-offset:2px}.shell{width:min(1160px,100%);margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}.brand small{color:#7dd3fc;font-weight:800;letter-spacing:.12em}.brand h1{font-size:28px;margin:5px 0}.nav{display:flex;gap:8px;flex-wrap:wrap}.nav a{min-height:44px;display:flex;align-items:center;color:#dbeafe;text-decoration:none;padding:0 13px;border:1px solid var(--line);border-radius:9px;background:#14243a}.status{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.pill,.card{border:1px solid var(--line);border-radius:15px;background:linear-gradient(145deg,#15263d,var(--card))}.pill{padding:14px}.pill span{display:block;color:var(--muted);font-size:11px;text-transform:uppercase}.pill strong{display:block;margin-top:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{padding:20px}.card h2{margin:0 0 5px;font-size:18px}.hint{color:var(--muted);font-size:12px;line-height:1.55}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:15px}.field{display:grid;gap:6px}.full{grid-column:1/-1}label{font-size:12px;font-weight:700;color:#d7e0ed}input,select{width:100%;min-height:44px;border:1px solid #3a516e;border-radius:9px;background:#091527;color:#fff;padding:0 11px}.switch{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;border:1px solid #39516f;border-radius:11px;background:#0a1728}.switch input{width:23px;height:23px;min-height:0;accent-color:var(--green)}.mode{margin-top:12px;padding:12px;border-radius:10px;background:#0a1728;color:#bfdbfe;font-size:13px}.profiles{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.chip{padding:7px 10px;border-radius:999px;background:#0a1728;color:#cbd5e1;font-size:12px}.save{width:100%;min-height:50px;margin-top:15px;border:0;border-radius:10px;background:#0284c7;color:#fff;font-weight:800;cursor:pointer}.feedback{margin-top:12px;min-height:40px;padding:11px;border-radius:8px;color:var(--muted);background:#0a1728}.ok{color:#86efac;border:1px solid #166534}.bad{color:#fca5a5;border:1px solid #991b1b}.disabled{opacity:.45;pointer-events:none}@media(max-width:800px){.grid{grid-template-columns:1fr}.status{grid-template-columns:1fr 1fr}.top{align-items:flex-start;flex-direction:column}}@media(max-width:480px){.shell{padding:14px}.status,.fields{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><div class='shell'>"
"<header class='top'><div class='brand'><small>AUBOT WAREHOUSE GATEWAY</small><h1>Cấu hình kết nối</h1></div><nav class='nav'><a href='/'>Quản lý kho</a><a href='/debug'>Chẩn đoán CAN</a><a href='/dang-xuat'>Đăng xuất</a></nav></header>"
"<section class='status'><div class='pill'><span>WiFi STA</span><strong id='stWifi'>Đang đọc...</strong></div><div class='pill'><span>Ethernet</span><strong id='stEth'>Đang đọc...</strong></div><div class='pill'><span>MQTT</span><strong id='stMqtt'>Đang đọc...</strong></div><div class='pill'><span>AP cấu hình</span><strong id='stAp'>Đang đọc...</strong><div style='display:flex;gap:6px;margin-top:8px'><button type='button' onclick='ap(1)'>Bật AP</button><button type='button' onclick='ap(0)'>Tắt AP</button></div></div></section>"
"<form id='form'><div class='grid'><section class='card'><h2>Gateway và truy cập</h2><p class='hint'>Mã Gateway tự sinh toàn bộ topic MQTT.</p><div class='fields'><div class='field'><label for='gateway_id'>Mã Gateway</label><input id='gateway_id' maxlength='16' required></div><div class='field'><label for='web_password'>Mật khẩu trang cấu hình</label><input id='web_password' type='password' placeholder='Để trống nếu không đổi'></div><div class='field full'><label for='ap_password'>Mật khẩu WiFi AP</label><input id='ap_password' type='password' minlength='8' required></div></div></section>"
"<section class='card'><h2>Ethernet W5500</h2><p class='hint'>Bật khi cắm vào router để lên mạng; tắt khi nối trực tiếp với máy tính để debug.</p><label class='switch' for='eth_router_mode'><span><b>Bật chế độ ETH qua router</b><br><small class='hint'>Cho phép Ethernet đi tới MQTT</small></span><input id='eth_router_mode' type='checkbox'></label><div id='ethModeText' class='mode'></div><div id='ethRouterFields' class='fields'><div class='field full'><label for='eth_dhcp'>Cấp địa chỉ</label><select id='eth_dhcp'><option value='1'>DHCP từ router</option><option value='0'>IP tĩnh mạng nhà máy</option></select></div><div class='field'><label for='eth_ip'>Địa chỉ IP</label><input id='eth_ip'></div><div class='field'><label for='eth_netmask'>Subnet mask</label><input id='eth_netmask'></div><div class='field'><label for='eth_gateway'>Gateway mạng</label><input id='eth_gateway'></div><div class='field'><label for='eth_dns'>DNS</label><input id='eth_dns'></div></div></section>"
"<section class='card'><h2>WiFi STA</h2><p class='hint'>Lưu tối đa 5 mạng; Gateway chọn mạng có tín hiệu mạnh nhất.</p><div class='fields'><div class='field full'><label for='wifi_ssid'>Tên WiFi mới</label><input id='wifi_ssid' list='nets'><datalist id='nets'></datalist></div><div class='field full'><label for='wifi_password'>Mật khẩu WiFi mới</label><input id='wifi_password' type='password'></div><div class='field full'><label for='wifi_dhcp'>Cấp địa chỉ</label><select id='wifi_dhcp'><option value='1'>DHCP</option><option value='0'>IP tĩnh</option></select></div><div class='field'><label for='wifi_ip'>Địa chỉ IP</label><input id='wifi_ip'></div><div class='field'><label for='wifi_netmask'>Subnet mask</label><input id='wifi_netmask'></div><div class='field'><label for='wifi_gateway'>Gateway mạng</label><input id='wifi_gateway'></div><div class='field'><label for='wifi_dns'>DNS</label><input id='wifi_dns'></div></div><div id='profiles' class='profiles'></div></section>"
"<section class='card'><h2>Máy chủ MQTT</h2><p class='hint'>MQTT tự dùng đường mạng đang hoạt động: Ethernet hoặc WiFi STA.</p><div class='fields'><div class='field full'><label for='mqtt_broker'>Địa chỉ broker</label><input id='mqtt_broker' placeholder='mqtt.example.com hoặc 192.168.1.10'></div><div class='field'><label for='mqtt_port'>Cổng</label><input id='mqtt_port' type='number' min='1' max='65535'></div><div class='field'><label for='mqtt_transport'>Bảo mật</label><select id='mqtt_transport'><option value='tcp'>TCP</option><option value='tls'>TLS xác thực CA</option></select></div><div class='field'><label for='mqtt_user'>Tên đăng nhập</label><input id='mqtt_user'></div><div class='field'><label for='mqtt_password'>Mật khẩu</label><input id='mqtt_password' type='password' placeholder='Để trống nếu không đổi'></div><div class='field full'><label for='publish_interval_ms'>Chu kỳ gửi trạng thái (ms)</label><input id='publish_interval_ms' type='number' min='250' max='60000'></div></div><p class='hint'>Topic: <b id='topic'>-</b></p></section></div><button class='save'>Lưu và áp dụng</button><div id='feedback' class='feedback'>Chưa có thay đổi.</div></form></div>"
"<script>const $=x=>document.getElementById(x),keys=['gateway_id','ap_password','wifi_dhcp','wifi_ip','wifi_netmask','wifi_gateway','wifi_dns','eth_dhcp','eth_ip','eth_netmask','eth_gateway','eth_dns','mqtt_broker','mqtt_port','mqtt_user','publish_interval_ms'];const esc=x=>String(x).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));function ethUi(){const on=$('eth_router_mode').checked;$('ethRouterFields').classList.toggle('disabled',!on);$('ethModeText').textContent=on?'ĐANG BẬT: dùng DHCP hoặc IP tĩnh bên dưới để vào mạng và MQTT.':'ĐANG TẮT: Ethernet cố định 169.254.1.1/16 để debug trực tiếp với máy tính.'}async function ap(enabled){await fetch('/api/gateway/ap',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({enabled})});status()}async function load(){const r=await fetch('/api/gateway/config');if(r.status===401){location='/dang-nhap';return}const c=await r.json();keys.forEach(k=>$(k).value=c[k]??'');$('eth_router_mode').checked=!!c.eth_router_mode;$('mqtt_transport').value=c.mqtt_transport;$('profiles').innerHTML=c.wifi_profiles.map(x=>`<span class='chip'>${esc(x)}</span>`).join('')||'<span class=hint>Chưa có mạng đã lưu</span>';$('topic').textContent=`gateway/${c.gateway_id}/warehouse/state`;ethUi();scan();status()}async function scan(){try{const d=await(await fetch('/api/gateway/wifi-scan')).json();$('nets').innerHTML=d.networks.map(x=>`<option value='${esc(x.ssid)}'>${x.rssi} dBm</option>`).join('')}catch(e){}}async function status(){try{const d=await(await fetch('/api/gateway/status')).json();$('stWifi').textContent=d.wifi.connected?`${d.wifi.ssid} - ${d.wifi.ip}`:'Chưa kết nối';$('stEth').textContent=d.ethernet.connected?d.ethernet.ip+(d.ethernet.uplink?' · UPLINK':' · DEBUG'):'Chưa kết nối';$('stMqtt').textContent=d.mqtt?'Đã kết nối':'Chưa kết nối';$('stAp').childNodes[0].nodeValue=d.ap?(d.ap_manual?'Đang phát · thủ công':'Đang phát · tự tắt sau 5 phút'):'Đã tắt'}catch(e){}setTimeout(status,1500)}$('eth_router_mode').onchange=ethUi;$('form').onsubmit=async e=>{e.preventDefault();const p=new URLSearchParams();keys.forEach(k=>p.set(k,$(k).value));p.set('eth_router_mode',$('eth_router_mode').checked?'1':'0');p.set('mqtt_transport',$('mqtt_transport').value);['web_password','mqtt_password','wifi_ssid','wifi_password'].forEach(k=>p.set(k,$(k).value));const f=$('feedback');f.textContent='Đang lưu cấu hình...';try{const r=await fetch('/api/gateway/config',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:p});if(!r.ok)throw Error(await r.text());f.textContent='Đã lưu. Cấu hình mạng mới đang được áp dụng.';f.className='feedback ok';setTimeout(load,1200)}catch(x){f.textContent='Không thể lưu: '+x.message;f.className='feedback bad'}};load()</script></body></html>";
